    internal static int WriteBooleanNullableRow(
        GraphBuilder graph,
        BooleanNullableRow value
    )
    {
        return value.Value switch
        {
            AndRow item => WriteAndRow(graph, item),
            OrRow item => WriteOrRow(graph, item),
            NotRow item => WriteNotRow(graph, item),
            EqualDecimalRow item => WriteEqualDecimalRow(graph, item),
            EqualStringRow item => WriteEqualStringRow(graph, item),
            EqualBooleanRow item => WriteEqualBooleanRow(graph, item),
            EqualDateRow item => WriteEqualDateRow(graph, item),
            EqualTimeRow item => WriteEqualTimeRow(graph, item),
            EqualDatetimeRow item => WriteEqualDatetimeRow(graph, item),
            EqualUuidRow item => WriteEqualUuidRow(graph, item),
            NotEqualDecimalRow item => WriteNotEqualDecimalRow(graph, item),
            NotEqualStringRow item => WriteNotEqualStringRow(graph, item),
            NotEqualBooleanRow item => WriteNotEqualBooleanRow(graph, item),
            NotEqualDateRow item => WriteNotEqualDateRow(graph, item),
            NotEqualTimeRow item => WriteNotEqualTimeRow(graph, item),
            NotEqualDatetimeRow item => WriteNotEqualDatetimeRow(graph, item),
            NotEqualUuidRow item => WriteNotEqualUuidRow(graph, item),
            GreaterThanDecimalRow item => WriteGreaterThanDecimalRow(graph, item),
            GreaterThanStringRow item => WriteGreaterThanStringRow(graph, item),
            GreaterThanBooleanRow item => WriteGreaterThanBooleanRow(graph, item),
            GreaterThanDateRow item => WriteGreaterThanDateRow(graph, item),
            GreaterThanTimeRow item => WriteGreaterThanTimeRow(graph, item),
            GreaterThanDatetimeRow item => WriteGreaterThanDatetimeRow(graph, item),
            GreaterThanUuidRow item => WriteGreaterThanUuidRow(graph, item),
            LessThanDecimalRow item => WriteLessThanDecimalRow(graph, item),
            LessThanStringRow item => WriteLessThanStringRow(graph, item),
            LessThanBooleanRow item => WriteLessThanBooleanRow(graph, item),
            LessThanDateRow item => WriteLessThanDateRow(graph, item),
            LessThanTimeRow item => WriteLessThanTimeRow(graph, item),
            LessThanDatetimeRow item => WriteLessThanDatetimeRow(graph, item),
            LessThanUuidRow item => WriteLessThanUuidRow(graph, item),
            GreaterThanOrEqualDecimalRow item => WriteGreaterThanOrEqualDecimalRow(graph, item),
            GreaterThanOrEqualStringRow item => WriteGreaterThanOrEqualStringRow(graph, item),
            GreaterThanOrEqualBooleanRow item => WriteGreaterThanOrEqualBooleanRow(graph, item),
            GreaterThanOrEqualDateRow item => WriteGreaterThanOrEqualDateRow(graph, item),
            GreaterThanOrEqualTimeRow item => WriteGreaterThanOrEqualTimeRow(graph, item),
            GreaterThanOrEqualDatetimeRow item => WriteGreaterThanOrEqualDatetimeRow(graph, item),
            GreaterThanOrEqualUuidRow item => WriteGreaterThanOrEqualUuidRow(graph, item),
            LessThanOrEqualDecimalRow item => WriteLessThanOrEqualDecimalRow(graph, item),
            LessThanOrEqualStringRow item => WriteLessThanOrEqualStringRow(graph, item),
            LessThanOrEqualBooleanRow item => WriteLessThanOrEqualBooleanRow(graph, item),
            LessThanOrEqualDateRow item => WriteLessThanOrEqualDateRow(graph, item),
            LessThanOrEqualTimeRow item => WriteLessThanOrEqualTimeRow(graph, item),
            LessThanOrEqualDatetimeRow item => WriteLessThanOrEqualDatetimeRow(graph, item),
            LessThanOrEqualUuidRow item => WriteLessThanOrEqualUuidRow(graph, item),
            InDecimalRow item => WriteInDecimalRow(graph, item),
            InStringRow item => WriteInStringRow(graph, item),
            InBooleanRow item => WriteInBooleanRow(graph, item),
            InDateRow item => WriteInDateRow(graph, item),
            InTimeRow item => WriteInTimeRow(graph, item),
            InDatetimeRow item => WriteInDatetimeRow(graph, item),
            InUuidRow item => WriteInUuidRow(graph, item),
            IfBooleanRow item => WriteIfBooleanRow(graph, item),
            CoalesceBooleanRow item => WriteCoalesceBooleanRow(graph, item),
            LiteralBoolean item => WriteLiteralBoolean(graph, item),
            ParamBoolean item => WriteParamBoolean(graph, item),
            FieldBoolean item => WriteFieldBoolean(graph, item),
            IfBooleanNullableRow item => WriteIfBooleanNullableRow(graph, item),
            CoalesceBooleanNullableRow item => WriteCoalesceBooleanNullableRow(graph, item),
            LiteralBooleanNullable item => WriteLiteralBooleanNullable(graph, item),
            ParamBooleanNullable item => WriteParamBooleanNullable(graph, item),
            FieldBooleanNullable item => WriteFieldBooleanNullable(graph, item),
            _ => throw GraphBuilder.Empty("BooleanNullableRow"),
        };
