    internal static BooleanNullableRow ReadBooleanNullableRow(IReadNode node)
    {
        return node.Label switch
        {
            "AndRow" => new BooleanNullableRow(ReadAndRow(node)),
            "OrRow" => new BooleanNullableRow(ReadOrRow(node)),
            "NotRow" => new BooleanNullableRow(ReadNotRow(node)),
            "EqualDecimalRow" => new BooleanNullableRow(ReadEqualDecimalRow(node)),
            "EqualStringRow" => new BooleanNullableRow(ReadEqualStringRow(node)),
            "EqualBooleanRow" => new BooleanNullableRow(ReadEqualBooleanRow(node)),
            "EqualDateRow" => new BooleanNullableRow(ReadEqualDateRow(node)),
            "EqualTimeRow" => new BooleanNullableRow(ReadEqualTimeRow(node)),
            "EqualDatetimeRow" => new BooleanNullableRow(ReadEqualDatetimeRow(node)),
            "EqualUuidRow" => new BooleanNullableRow(ReadEqualUuidRow(node)),
            "NotEqualDecimalRow" => new BooleanNullableRow(ReadNotEqualDecimalRow(node)),
            "NotEqualStringRow" => new BooleanNullableRow(ReadNotEqualStringRow(node)),
            "NotEqualBooleanRow" => new BooleanNullableRow(ReadNotEqualBooleanRow(node)),
            "NotEqualDateRow" => new BooleanNullableRow(ReadNotEqualDateRow(node)),
            "NotEqualTimeRow" => new BooleanNullableRow(ReadNotEqualTimeRow(node)),
            "NotEqualDatetimeRow" =>
